295       localparam   LLENWORDSPERLINE = P.DCACHE_LINELENINBITS/P.LLEN;             // Number of LLEN words in cacheline
296       localparam   LLENLOGBWPL = $clog2(LLENWORDSPERLINE);                       // Log2 of ^
297       localparam   BEATSPERLINE = P.DCACHE_LINELENINBITS/P.AHBW;                 // Number of AHBW words (beats) in cacheline
298       localparam   AHBWLOGBWPL = $clog2(BEATSPERLINE);                           // Log2 of ^
299       localparam   LINELEN = P.DCACHE_LINELENINBITS;                             // Number of bits in cacheline
300       localparam   LLENPOVERAHBW = P.LLEN / P.AHBW;                              // Number of AHB beats in a LLEN word. AHBW cannot be larger than LLEN. (implementation limitation)
301       localparam   CACHEWORDLEN = P.ZICCLSM_SUPPORTED ? 2*P.LLEN : P.LLEN;       // Width of the cache's input and output data buses.  Misaligned doubles width for fast access
302 
303       logic [LINELEN-1:0]      FetchBuffer;                                      // Temporary buffer to hold partially fetched cacheline
304       logic [P.PA_BITS-1:0]    DCacheBusAdr;                                     // Cacheline address to fetch or writeback.
305       logic [AHBWLOGBWPL-1:0]  BeatCount;                                        // Position within a cacheline.  ahbcacheinterface to cache
306       logic                    DCacheBusAck;                                     // ahbcacheinterface completed fetch or writeback
307       logic                    SelBusBeat;                                       // ahbcacheinterface selects position in cacheline with BeatCount
308       logic [1:0]              CacheBusRW;                                       // Cache sends request to ahbcacheinterface
309       logic [1:0]              BusRW;                                            // Uncached bus memory access
310       logic                    CacheableOrFlushCacheM;                           // Memory address is cacheable or operation is a cache flush
311       logic [1:0]              CacheRWM;                                         // Cache read (10), write (01), AMO (11)
312       logic                    FlushDCache;                                      // Suppress d cache flush if there is an ITLB miss.
313       logic                    BusCMOZero;
314       logic [3:0]              CacheCMOpM;
315       logic                    BusAtomic;
316 
317       if(P.ZICBOZ_SUPPORTED) begin
318         assign BusCMOZero = LSUCMOpM[3] & ~CacheableM;
319         assign CacheCMOpM = (CacheableM & ~SelHPTW) ? CMOpM : '0;
320         assign BusAtomic = AtomicM[1] & ~CacheableM;
321       end else begin
322         assign BusCMOZero = 1'b0;
323         assign CacheCMOpM = '0;
324         assign BusAtomic = 1'b0;
325       end
326       assign BusRW = (~CacheableM & ~SelDTIM )? LSURWM : '0;
327       assign CacheableOrFlushCacheM = CacheableM | FlushDCacheM;
328       assign CacheRWM = (CacheableM & ~SelDTIM) ? LSURWM : '0;
329       assign FlushDCache = FlushDCacheM & ~(SelHPTW);
